//! The built-in English lexicon: word frequencies and common word pairs.
//!
//! Both tables are generated by `tools/gen_data.swift`.

use std::collections::HashMap;
use std::sync::OnceLock;

static WORDS: &str = include_str!("../data/words.txt");
static BIGRAMS: &str = include_str!("../data/bigrams.txt");

pub struct Entry {
    /// Canonical spelling, e.g. "London".
    pub word: &'static str,
    /// Lowercase ASCII form used for matching.
    pub lower: &'static str,
    /// Natural log of the word's relative frequency.
    pub logp: f32,
}

pub struct Dict {
    pub entries: Vec<Entry>,
    index: HashMap<&'static str, u32>,
    /// Entry indices ordered by `lower`, for prefix lookups.
    sorted: Vec<u32>,
    /// For each lowercase word, the words most often seen after it with a
    /// weight in (0, 1] relative to the most common follower.
    followers: HashMap<&'static str, Vec<(u32, f32)>>,
}

impl Dict {
    fn load() -> Dict {
        let mut raw: Vec<(&'static str, f64)> = Vec::with_capacity(60_000);
        let mut total = 0.0f64;
        for line in WORDS.lines() {
            if let Some((word, count)) = line.split_once('\t') {
                if let Ok(count) = count.parse::<f64>() {
                    total += count;
                    raw.push((word, count));
                }
            }
        }

        let mut entries = Vec::with_capacity(raw.len());
        let mut index = HashMap::with_capacity(raw.len());
        for (i, (word, count)) in raw.into_iter().enumerate() {
            // The dictionary lives for the whole process, so the handful of
            // lowercased proper nouns can simply be leaked.
            let lower: &'static str = if word.bytes().any(|b| b.is_ascii_uppercase()) {
                Box::leak(word.to_ascii_lowercase().into_boxed_str())
            } else {
                word
            };
            index.insert(lower, i as u32);
            entries.push(Entry { word, lower, logp: (count / total).ln() as f32 });
        }

        let mut sorted: Vec<u32> = (0..entries.len() as u32).collect();
        sorted.sort_unstable_by_key(|&i| entries[i as usize].lower);

        let mut followers: HashMap<&'static str, Vec<(u32, f32)>> = HashMap::new();
        for line in BIGRAMS.lines() {
            let mut parts = line.split('\t');
            let (Some(first), Some(second), Some(count)) = (parts.next(), parts.next(), parts.next()) else {
                continue;
            };
            let Ok(count) = count.parse::<f32>() else { continue };
            let Some(&id) = index.get(second.to_ascii_lowercase().as_str()) else { continue };
            followers.entry(first).or_default().push((id, count));
        }
        // Lines are grouped by first word, most frequent pair first.
        for list in followers.values_mut() {
            let top = list[0].1;
            for (_, weight) in list.iter_mut() {
                *weight /= top;
            }
        }

        Dict { entries, index, sorted, followers }
    }

    pub fn get() -> &'static Dict {
        static DICT: OnceLock<Dict> = OnceLock::new();
        DICT.get_or_init(Dict::load)
    }

    pub fn lookup(&self, lower: &str) -> Option<&Entry> {
        self.index.get(lower).map(|&i| &self.entries[i as usize])
    }

    pub fn contains(&self, lower: &str) -> bool {
        self.index.contains_key(lower)
    }

    /// Entries whose lowercase form starts with `prefix`.
    pub fn with_prefix<'a>(&'a self, prefix: &'a str) -> impl Iterator<Item = &'a Entry> + 'a {
        let lo = self.sorted.partition_point(|&i| self.entries[i as usize].lower < prefix);
        self.sorted[lo..]
            .iter()
            .map(move |&i| &self.entries[i as usize])
            .take_while(move |e| e.lower.starts_with(prefix))
    }

    /// Words that commonly follow `lower`, most likely first.
    pub fn followers<'a>(&'a self, lower: &str) -> impl Iterator<Item = (&'a Entry, f32)> + 'a {
        self.followers
            .get(lower)
            .into_iter()
            .flatten()
            .map(move |&(i, weight)| (&self.entries[i as usize], weight))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn loads() {
        let d = Dict::get();
        assert!(d.entries.len() > 40_000);
        assert_eq!(d.lookup("london").unwrap().word, "London");
        assert_eq!(d.lookup("i").unwrap().word, "I");
        assert!(d.contains("keyboard"));
        assert!(!d.contains("teh"));
    }

    #[test]
    fn prefixes() {
        let d = Dict::get();
        let words: Vec<_> = d.with_prefix("keyb").map(|e| e.lower).collect();
        assert!(words.contains(&"keyboard"));
        assert!(words.iter().all(|w| w.starts_with("keyb")));
        assert_eq!(d.with_prefix("zzzzzz").count(), 0);
    }

    #[test]
    fn follower_weights() {
        let d = Dict::get();
        let f: Vec<_> = d.followers("i").map(|(e, w)| (e.word, w)).collect();
        assert_eq!(f[0], ("have", 1.0));
        assert!(f.iter().all(|&(_, w)| w > 0.0 && w <= 1.0));
        assert!(f.windows(2).all(|p| p[0].1 >= p[1].1));
    }
}
